const meta = {
  component: Button,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nRender a button or give another element the appearance of a button.\n\n**Import:** `@/registry/erbium/ui/button`\n\n## Usage\n\n```tsx\nimport { Button } from \"@/registry/erbium/ui/button\";\n```\n\n```tsx\n<Button variant=\"outline\">Button</Button>\n```\n\n## Keyboard shortcuts\n\nPass `hotkey` to register a shortcut that clicks the button while it is mounted, enabled, and not loading. Clicking runs `onClick`, submits a form, or follows a rendered link, the same as a pointer press. The button sets `aria-keyshortcuts` for chords and shows the shortcut in a badge above itself while the user holds one of the shortcut's modifiers (see `KbdHint` for placement). Place a `ButtonShortcut` inside to label the shortcut permanently instead; it reads the button's `hotkey` when it has none of its own.\n\n```tsx\n<Button hotkey=\"Mod+S\" onClick={save}>\n  Save\n  <ButtonShortcut />\n</Button>\n```\n\nThe registration is named after `aria-label` or `title` for TanStack Hotkeys devtools and shortcut lists. While a modal dialog is open, shortcuts registered outside it pause, so a page button's shortcut cannot fire behind the dialog.\n\n## Cursor\n\nTailwind v4 [switched](https://tailwindcss.com/docs/upgrade-guide#buttons-use-the-default-cursor) from `cursor: pointer` to `cursor: default` for the button component.\n\nTo keep the `cursor: pointer` behavior, add `cursor-pointer` to your buttons.\n\nYou can also enable this during project setup with `npx shadcn@latest init --pointer`.\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Button](https://base-ui.com/react/components/button)\n\n## Keyboard shortcuts\n\n`hotkey` registers its shortcut with TanStack Hotkeys and reveals it with `useHotkeyHint`.\n\n- [useHotkey](https://tanstack.com/hotkeys/latest/docs/framework/react/reference/functions/useHotkey)\n- [Hotkey hints](https://tanstack.com/hotkeys/latest/docs/framework/react/guides/hotkey-hints)",
      },
    },
    layout: "centered",
  },
} satisfies Meta<typeof Button>;

export default { ...meta, title: "Components/Button",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Button> = {
  argTypes: {
    loading: {
      control: "boolean",
      description: "Show a spinner and block activation while an action runs.",
    },
    size: {
      control: "select",
      description: "Button size, including icon-only sizes.",
      options: ["default", "xs", "sm", "lg", "icon", "icon-xs", "icon-sm", "icon-lg"],
      table: { defaultValue: { summary: "default" } },
    },
    variant: {
      control: "select",
      description: "Visual style of the button.",
      options: [
        "default",
        "outline",
        "ghost",
        "error",
        "ghost-error",
        "ghost-success",
        "ghost-warning",
        "ghost-info",
        "secondary",
        "link",
      ],
      table: { defaultValue: { summary: "default" } },
    },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "Use the Controls panel to try every `variant` and `size` in the Button API reference." },
      source: { code: "import { Icon } from \"@/registry/erbium/ui/icon\";\nimport { Button } from \"@/registry/erbium/ui/button\";\nimport type * as React from \"react\";\n\nexport const defaultProps = {\n  loading: false,\n  size: \"default\",\n  variant: \"default\",\n} satisfies React.ComponentProps<typeof Button>;\n\nexport default function ButtonPlaygroundExample(\n  args: React.ComponentProps<typeof Button> = defaultProps,\n) {\n  const iconOnly = args.size?.startsWith(\"icon\") === true;\n\n  return (\n    <Button {...args} aria-label={iconOnly ? \"Submit\" : undefined}>\n      {iconOnly ? <Icon name=\"arrow-up-01\" /> : \"Button\"}\n    </Button>\n  );\n}\n" },
    },
  },
  render: PlaygroundExample,
};

